 async function logout(){await supabase.auth.signOut();setSession(null)}
 async function createProject(ev){
  ev.preventDefault();if(!can('can_edit_projects')){setError('Permission denied');return}setSaving(true);setError('');
  const payload={...form,client_id:form.client_id||null,progress:Number(form.progress||0),status_label:form.status_label||'Design Running',status:statusToEnum(form.status_label),priority:form.priority||'Normal',deadline_date:form.deadline_date||null,revision_count:Number(form.revision_count||0),assigned_designer_name:form.assigned_designer_name||null,assigned_pasting_name:form.assigned_pasting_name||null,assigned_marketing_name:form.assigned_marketing_name||null};if(!can('can_update_payments')){const oldPayment=editProjectId?projects.find(x=>x.id===editProjectId):null;payload.total_bill=oldPayment?.total_bill??0;payload.advance=oldPayment?.advance??0;payload.paid_on_completion=oldPayment?.paid_on_completion??0;}delete payload.id;
  let result,historyError='';
  if(editProjectId){
   const old=projects.find(x=>x.id===editProjectId);
   result=await supabase.from('projects').update(payload).eq('id',editProjectId);
   if(!result.error){
    const changed=[];
    if(Number(old?.progress||0)!==Number(payload.progress))changed.push(`Progress ${old?.progress||0}% → ${payload.progress}%`);
    if(old?.status_label!==payload.status_label)changed.push(`Status ${old?.status_label||'—'} → ${payload.status_label}`);
    if(old?.status_comment!==payload.status_comment)changed.push('Status comment changed');
    if(old?.assigned_designer_name!==payload.assigned_designer_name)changed.push('Designer changed');
    if(old?.assigned_pasting_name!==payload.assigned_pasting_name)changed.push('Pastingman changed');
     if(old?.assigned_marketing_name!==payload.assigned_marketing_name)changed.push('Marketing Officer changed');
    const {error:he}=await supabase.from('project_updates').insert({project_id:editProjectId,author_id:session.user.id,designer_name:payload.assigned_designer_name,progress:Number(payload.progress||0),status:statusToEnum(payload.status_label),comment:payload.status_comment||''});
    if(he)historyError=he.message;
   }
  }else{
   result=await supabase.from('projects').insert({...payload,status:statusToEnum(payload.status_label)}).select().single();
   if(!result.error){const {error:he}=await supabase.from('project_updates').insert({project_id:result.data.id,author_id:session.user.id,designer_name:payload.assigned_designer_name,progress:Number(payload.progress||0),status:statusToEnum(payload.status_label),comment:payload.status_comment||''});if(he)historyError=he.message}
  }
  if(result.error)setError(result.error.message);
  else{setModal(false);setEditProjectId(null);setForm({project_name:'',client_id:'',project_location:'',work_types:[],client_requirement:'',start_date:'',handover_date:'',assigned_designer_name:'',assigned_pasting_name:'',assigned_marketing_name:'',progress:0,status_label:'Design Running',status_comment:'',priority:'Normal',deadline_date:'',revision_count:0,total_bill:0,advance:0,paid_on_completion:0});await loadData();if(historyError)setError('Project saved, but history entry failed: '+historyError)}
  setSaving(false)
 }
